const motion=!matchMedia('(prefers-reduced-motion: reduce)').matches;if(motion&&'IntersectionObserver'in window){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));}
const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Menü schließen':'Menü öffnen');document.querySelector('nav').classList.toggle('open',open)});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');document.querySelector('nav').classList.remove('open')}));
const demos=[['STORY-KETTE · VERTRAUEN','Dein erster Besuch?<br>Du musst nichts wissen.','Zeige in drei Stories: Wie läuft die Beratung ab? Wie wählst du die passende Behandlung? Wie kann eine Interessentin ihre Fragen stellen?','„Du bist unsicher, welche Behandlung passt? Schreib mir deine Frage — wir finden es gemeinsam heraus.“'],['POST · FREIE TERMINE','Ein Moment nur für dich.<br>Diese Woche in deinem Studio.','Zeige einen Einblick in die Behandlung und nenne die tatsächlich freien Zeiten. Erkläre, für wen das Angebot passt. Gib einen direkten Weg zur Anfrage an.','„Du möchtest dir eine Auszeit nehmen? Frag deinen Wunschtermin über den Link in meinem Profil an.“'],['REEL · EXPERTISE','Drei Fragen, die du<br>vorher stellen darfst.','Erkläre drei häufige Fragen zu einer deiner Behandlungen: Für wen ist sie geeignet? Was passiert beim Termin? Was sollte danach beachtet werden?','„Speichere dir die Antworten für deinen nächsten Besuch. Für persönliche Fragen bin ich gerne für dich da.“']];const tabs=[...document.querySelectorAll('[data-demo]')];function selectDemo(i){tabs.forEach((t,j)=>{t.setAttribute('aria-selected',j===i);t.tabIndex=j===i?0:-1});document.querySelector('#demo-type').textContent=demos[i][0];document.querySelector('#demo-title').innerHTML=demos[i][1];document.querySelector('#demo-text').textContent=demos[i][2];document.querySelector('#demo-cta').textContent=demos[i][3]}tabs.forEach((t,i)=>{t.tabIndex=i? -1:0;t.addEventListener('click',()=>selectDemo(i));t.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const j=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;selectDemo(j);tabs[j].focus()}})});
const order=document.querySelector('#order-dialog');document.querySelector('#order').addEventListener('click',()=>order.showModal());document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});document.querySelector('.close-action').addEventListener('click',()=>order.close());
const legal=document.querySelector('#legal-dialog');const legalCopy={imprint:['Impressum','<p>Phinix Media · Beauty Booking System™</p><p>Diese Seite stellt das Produktkonzept vor. Der Verkauf ist noch nicht geöffnet.</p><p>Die vollständigen Anbieterangaben — rechtlicher Name, ladungsfähige Anschrift und Kontakt — werden vor Verkaufsstart ergänzt. Aktuell werden auf dieser Seite keine Bestellungen angenommen.</p>'],privacy:['Datenschutz','<p>Diese Website enthält kein Kontaktformular und verwendet keine Analyse- oder Marketing-Cookies. Eingaben in den interaktiven Beispielen werden nicht gespeichert.</p><p>Beim Abruf der Website verarbeitet der Hosting-Anbieter technisch erforderliche Verbindungsdaten. Die Schriftarten werden lokal bereitgestellt.</p><p>Die vollständigen Angaben zum Verantwortlichen und zu den eingesetzten Hosting-Diensten werden vor Verkaufsstart ergänzt.</p>']};document.querySelectorAll('[data-legal]').forEach(b=>b.addEventListener('click',()=>{const c=legalCopy[b.dataset.legal];document.querySelector('#legal-title').textContent=c[0];document.querySelector('#legal-text').innerHTML=c[1];legal.showModal()}));
